    def get_portfolio(self):
        """
        [Required]

        获取投资组合。系统初始化时，会调用此接口，获取包含账户信息、持仓、净值、份额等内容的投资组合

        :return: Portfolio
        """
        raise NotImplementedError
    @abc.abstractmethod
    def submit_order(self, order):
        """
        提交订单

        :param order: 订单
        :type order: :class:`~Order`
        """
        raise NotImplementedError
    @abc.abstractmethod
    def cancel_order(self, order):
        """
        撤单

        :param order: 订单
        :type order: :class:`~Order`
        """
        raise NotImplementedError
    @abc.abstractmethod
    def get_open_orders(self, symbol=None):
        """
        [Required]

        查询当前未完成的指定/所有订单。

        :return: list[:class:`~Order`]
        """
        raise NotImplementedError
    @abc.abstractmethod
    def get_orders(self, symbol=None):
        """
        [Required]
        查询指定/所有订单。

        :return: list[:class:`~Order`]
        """
        raise NotImplementedError
    @abc.abstractmethod
    def scheme_order(self, **kwargs):
        """
        算法方案创建
        :return:
        """
        raise NotImplementedError()
    @abc.abstractmethod
    def scheme_control(self, **kwargs):
        """
        算法方案控制
        :return:
        """
        raise NotImplementedError()
    @abc.abstractmethod
    def get_scheme_status(self, **kwargs):
        """
        获取方案状态
        :return:
        """
        raise NotImplementedError()
    @abc.abstractmethod
    def get_schemedetail_status(self, **kwargs):
        """
        获取算法状态
        :return:
        """
        raise NotImplementedError()
