class AbstractCommission(six.with_metaclass(abc.ABCMeta)):
    __doc__ = '税费计算类基类'
    @abc.abstractmethod
    def calculate_commission(self, trade):
        """计算订单的税费

        Args:
            trade(Trade): 交易对象

        Returns:
            val(float): 订单的税费额
            val2(float): 欠款，临时多交的税，税费计算时单个订单可能会有最小税费额，
            当第一次产生交易的税费额小于最小税费额时需要按照最小税费额计算，
            当再次产生交易时需要少交之前交易补齐到最小税费额的部分
        """
        raise NotImplementedError()
